const sql = "SELECT door, granted FROM door_acl WHERE badge = '" + badge + "'";
db.exec(sql); // exec runs a batch: one ';' and the attacker's second statement rides along

vulnerableCodeVariants.code:
// VULNERABLE - mysql2 multipleStatements:true lets a stacked ';' run a second command
const conn = await mysql.createConnection({ host, user, database, multipleStatements: true });
const sql = "SELECT door, granted FROM door_acl WHERE badge = '" + badge + "'";
const [results] = await conn.query(sql);
// After the badge read, "; UPDATE door_acl SET granted=1 WHERE door='VAULT'" rides in as its own statement.

// VULNERABLE - exec() runs the entire string; emulated prepares also allow stacking
$sql = "SELECT door, granted FROM door_acl WHERE badge = '$badge'";
$pdo->exec($sql);
// After the read, "; UPDATE door_acl SET granted=1 WHERE door='VAULT'" runs as a second statement.

// VULNERABLE - Statement.execute() runs the concatenated string as a batch
Statement st = conn.createStatement();
st.execute(
    "SELECT door, granted FROM door_acl WHERE badge = '" + badge + "'");
// MySQL needs allowMultiQueries=true; then "; UPDATE door_acl SET granted=1 ..." rides in.

// VULNERABLE - one SqlCommand text holds several statements; SQL Server runs them all
using var cmd = new SqlCommand(
    "SELECT door, granted FROM door_acl WHERE badge = '" + badge + "'", conn);
using var reader = cmd.ExecuteReader();
// The stacked "; UPDATE door_acl SET granted=1 WHERE door='VAULT'" rides in as its own statement.

// VULNERABLE - Exec() sends the concatenated string; batch-capable drivers run it all
sql := "SELECT door, granted FROM door_acl WHERE badge = '" + badge + "'"
_, err := db.Exec(sql)
// The stacked "; UPDATE door_acl SET granted=1 WHERE door='VAULT'" rides in as its own statement.

// VULNERABLE - DB::unprepared() runs the raw string with no binding, batch and all
$sql = "SELECT door, granted FROM door_acl WHERE badge = '$badge'";
DB::unprepared($sql);
// The stacked "; UPDATE door_acl SET granted=1 WHERE door='VAULT'" rides in as its own statement.

// VULNERABLE - JdbcTemplate.execute() runs the concatenated string as a batch
String sql = "SELECT door, granted FROM door_acl WHERE badge = '" + badge + "'";
jdbcTemplate.execute(sql);
// The stacked "; UPDATE door_acl SET granted=1 WHERE door='VAULT'" rides in as its own statement.

secureCode.code:
// SECURE - bind the value AND use an API that runs exactly ONE statement
const rows = db.prepare('SELECT door, granted FROM door_acl WHERE badge = ?').all(badge);
// prepare()/get()/all() execute a single statement - a stacked ';' becomes a syntax error, not a command.
// Least privilege backs this up: the read path's DB role should hold SELECT only, never UPDATE.

secureCodeVariants.code:
// SECURE - multipleStatements stays OFF and the value is bound, so only ONE statement runs
const conn = await mysql.createConnection({ host, user, database /* multipleStatements: false */ });
const [rows] = await conn.execute(
  'SELECT door, granted FROM door_acl WHERE badge = ?', [badge]);
// A stacked ';' is now an inert literal inside the badge, not a second command.

// SECURE - a real prepared statement binds the value and runs exactly one statement
$pdo->setAttribute(PDO::ATTR_EMULATE_PREPARES, false);
$stmt = $pdo->prepare('SELECT door, granted FROM door_acl WHERE badge = ?');
$stmt->execute([$badge]);
// The stacked ';' is now an inert literal inside the badge, not a second command.

// SECURE - PreparedStatement binds the value and runs a single statement
PreparedStatement ps = conn.prepareStatement(
    "SELECT door, granted FROM door_acl WHERE badge = ?");
ps.setString(1, badge);
ResultSet rs = ps.executeQuery();
// The ';'-payload becomes an inert string literal, never a second command.

// SECURE - bind via SqlParameter; the command runs a single parameterized statement
using var cmd = new SqlCommand(
    "SELECT door, granted FROM door_acl WHERE badge = @badge", conn);
cmd.Parameters.Add(new SqlParameter("@badge", badge));
using var reader = cmd.ExecuteReader();
// A stacked ';' rides inside @badge as data, never as a second command.

// SECURE - the value binds to a placeholder and one statement runs
rows, err := db.Query(
    "SELECT door, granted FROM door_acl WHERE badge = ?", badge)
// The ';'-payload becomes an inert string literal, not a second command.
// Postgres uses $1 instead of ?; either way the driver runs a single statement.

// SECURE - the Query Builder binds the value and issues one prepared statement
$rows = DB::table('door_acl')
    ->where('badge', $badge)
    ->get();
// A stacked ';' is now an inert literal inside the badge, not a second command.

// SECURE - JdbcTemplate binds the arg to a ? placeholder; one statement runs
